import{_ as t,o,c as n,a4 as a}from"./chunks/framework.bruR1JhL.js";const p=JSON.parse('{"title":"LaTeX","description":"Write LaTeX documents with highlighting, completion and a PDF preview that updates as you type.","frontmatter":{"title":"LaTeX","description":"Write LaTeX documents with highlighting, completion and a PDF preview that updates as you type."},"headers":[],"relativePath":"docs/latex.md","filePath":"docs/latex.md","lastUpdated":1795509372000}'),r={name:"docs/latex.md"};function s(i,e,d,l,c,h){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="latex" tabindex="-1">LaTeX <a class="header-anchor" href="#latex" aria-label="Permalink to &quot;LaTeX&quot;">​</a></h1><p>The LaTeX category has one tool, the LaTeX editor. You write the source on the left and see the compiled PDF on the right. Errors and warnings are listed with their line, and clicking one takes you there.</p><p>Start a new document from a template, click <strong>Open .tex file…</strong>, or right-click a <code>.tex</code> file in the Explorer and choose <strong>Open in LaTeX editor</strong>. See <a href="/tilepress/docs/interface">The Tilepress window</a> for the Explorer and the other general controls.</p><h2 id="latex-editor" tabindex="-1">LaTeX editor <a class="header-anchor" href="#latex-editor" aria-label="Permalink to &quot;LaTeX editor&quot;">​</a></h2><p>A LaTeX editor with syntax highlighting, command completion, snippets and a live PDF preview. It compiles with Tectonic, which Tilepress sets up on first launch, or with a LaTeX distribution you already have.</p><h3 id="how-to-use-it" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>On the start screen, under <strong>New document</strong>, click <strong>Article</strong>, <strong>Report (chapters)</strong>, <strong>Presentation (Beamer)</strong> or <strong>Letter</strong>. Or click <strong>Open .tex file…</strong>, or <strong>Open</strong> followed by the name of the <code>.tex</code> file selected in the Explorer. Files you opened recently are listed under <strong>Recent</strong>.</li><li>Type in the editor on the left. With <strong>Live</strong> ticked, the PDF on the right is rebuilt a moment after you stop typing. Otherwise click <strong>Compile</strong>.</li><li>If the panel under the editor lists errors, click one to jump to its line.</li><li>For a new document, click <strong>Save as…</strong> to keep it where you want it. For an existing file, click <strong>Save</strong> or press <kbd>Ctrl</kbd>+<kbd>S</kbd>.</li><li>Use <strong>Open PDF</strong> or <strong>Show in folder</strong> above the preview to get at the PDF.</li></ol><h3 id="the-toolbar" tabindex="-1">The toolbar <a class="header-anchor" href="#the-toolbar" aria-label="Permalink to &quot;The toolbar&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th></tr></thead><tbody><tr><td><strong>New…</strong></td><td>Starts a new document from one of the four templates.</td></tr><tr><td><strong>Open…</strong></td><td>Opens a <code>.tex</code> file.</td></tr><tr><td><strong>Save</strong></td><td>Saves the document. A dot (<strong>Save •</strong>) means there are unsaved changes. On a new document it opens <strong>Save as…</strong>.</td></tr><tr><td><strong>Save as…</strong></td><td>Saves the document under a new name or in another folder, and goes on editing that copy.</td></tr><tr><td><strong>Insert…</strong></td><td>Inserts a snippet (see below).</td></tr><tr><td><strong>Image…</strong></td><td>Inserts a figure for a picture you choose (see below).</td></tr><tr><td>Document name</td><td>The file&#39;s name, or <strong>Untitled</strong> for a new document that hasn&#39;t been saved with <strong>Save as…</strong>. Hover to see the full path.</td></tr><tr><td><strong>Engine</strong></td><td><strong>Engine: automatic</strong>, or one of the LaTeX engines found on your PC.</td></tr><tr><td><strong>Live</strong></td><td>Recompiles a moment after you stop typing. On by default; the app remembers your choice.</td></tr><tr><td><strong>Compile</strong></td><td>Compiles now. Disabled until a LaTeX engine is ready.</td></tr></tbody></table><h3 id="templates" tabindex="-1">Templates <a class="header-anchor" href="#templates" aria-label="Permalink to &quot;Templates&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Template</th><th>What you get</th></tr></thead><tbody><tr><td><strong>Article</strong></td><td>An 11 pt article with amsmath, amssymb, graphicx and hyperref, 2.5 cm margins, a title and a sample equation.</td></tr><tr><td><strong>Report (chapters)</strong></td><td>An 11 pt report with a title page, a table of contents and two chapters.</td></tr><tr><td><strong>Presentation (Beamer)</strong></td><td>A Beamer presentation (Madrid theme) with a title slide and one slide with a list.</td></tr><tr><td><strong>Letter</strong></td><td>A letter with sender address, recipient, opening and closing.</td></tr></tbody></table><h3 id="snippets" tabindex="-1">Snippets <a class="header-anchor" href="#snippets" aria-label="Permalink to &quot;Snippets&quot;">​</a></h3><p><strong>Insert…</strong> offers Section, Subsection, Bold, Italic, Bulleted list, Numbered list, Inline math, Equation, Aligned equations, Fraction, Table, Footnote, Link and Page break. The cursor lands where you type next. If you have text selected, the snippet goes round it: select a word and choose <strong>Bold</strong> to get <code>\\textbf{word}</code>.</p><p><strong>Image…</strong> asks for a picture (JPG, PNG, GIF, BMP, TIFF, WebP, PDF or EPS) and inserts a <code>figure</code> with <code>\\includegraphics</code>, a caption and a label. The picture&#39;s path is written relative to the <code>.tex</code> file, with forward slashes. A picture on a different drive gets its full path. The figure needs the graphicx package, which the Article and Report templates already load.</p><div class="tip custom-block"><p class="custom-block-title">Save before you add pictures</p><p>A new document lives in Tilepress&#39;s own folder until you use <strong>Save as…</strong>, so a relative picture path would point from there. Save the document where you want it first, then add pictures.</p></div><h3 id="completion-and-keyboard-shortcuts" tabindex="-1">Completion and keyboard shortcuts <a class="header-anchor" href="#completion-and-keyboard-shortcuts" aria-label="Permalink to &quot;Completion and keyboard shortcuts&quot;">​</a></h3><p>Type <code>\\</code> and a few letters to see matching commands, such as <code>\\section</code>, <code>\\textbf</code>, <code>\\includegraphics</code> or Greek letters. After <code>\\begin{</code>, the list offers environments such as <code>itemize</code>, <code>equation</code>, <code>align</code>, <code>figure</code>, <code>table</code>, <code>tabular</code> and <code>frame</code>.</p><table tabindex="0"><thead><tr><th>Keys</th><th>Action</th></tr></thead><tbody><tr><td><kbd>Ctrl</kbd>+<kbd>S</kbd></td><td>Save (Save as for a new document)</td></tr><tr><td><kbd>Ctrl</kbd>+<kbd>Enter</kbd></td><td>Compile</td></tr><tr><td><kbd>Ctrl</kbd>+<kbd>Space</kbd></td><td>Show the completion list after a <code>\\</code></td></tr><tr><td><kbd>Tab</kbd> / <kbd>Shift</kbd>+<kbd>Tab</kbd></td><td>Indent / unindent the line or selection</td></tr><tr><td><kbd>Ctrl</kbd>+<kbd>F</kbd></td><td>Find and replace in the source</td></tr><tr><td><kbd>Ctrl</kbd>+<kbd>Z</kbd> / <kbd>Ctrl</kbd>+<kbd>Y</kbd></td><td>Undo / redo</td></tr></tbody></table><h3 id="errors-warnings-and-the-log" tabindex="-1">Errors, warnings and the log <a class="header-anchor" href="#errors-warnings-and-the-log" aria-label="Permalink to &quot;Errors, warnings and the log&quot;">​</a></h3><p>The panel under the editor says how the last compile went, for example &quot;Compiled with tectonic in 1.4 s&quot; or &quot;Compilation failed&quot;, and counts the errors and warnings. Click an error or warning that has a line number to select that line in the editor. Click <strong>Show log</strong> to read the engine&#39;s full output, and <strong>Hide log</strong> to go back to the list.</p><p>When a compile fails, the preview keeps the last PDF that worked and says &quot;showing the last good version&quot;.</p><h3 id="latex-engines" tabindex="-1">LaTeX engines <a class="header-anchor" href="#latex-engines" aria-label="Permalink to &quot;LaTeX engines&quot;">​</a></h3><p>With <strong>Engine: automatic</strong>, the editor uses the first engine it finds, in this order: Tectonic, latexmk, pdfLaTeX, XeLaTeX, LuaLaTeX. Choose an engine from the <strong>Engine</strong> list to use a particular one. The list shows the program names: <code>tectonic</code>, <code>latexmk</code>, <code>pdflatex</code>, <code>xelatex</code>, <code>lualatex</code>.</p><p>Tilepress finds engines that are on your PATH, MiKTeX in its standard folders (in <code>%LOCALAPPDATA%\\Programs\\MiKTeX</code> or <code>Program Files\\MiKTeX</code>), TeX Live under <code>C:\\texlive</code>, and its own copy of Tectonic.</p><p><strong>First launch.</strong> If no engine is found when Tilepress starts, it downloads Tectonic 0.15.0 (about 19 MB) from Tectonic&#39;s GitHub releases in the background, checks the download against its SHA-256 checksum, and installs it in <code>%LOCALAPPDATA%\\Tilepress\\tectonic</code>. It then compiles a small test document once, so Tectonic downloads the packages most documents need (fonts, amsmath, amssymb, graphicx, hyperref). This takes a few minutes and happens only once. The rest of the app works meanwhile, and the editor shows a banner with the progress:</p><ul><li>&quot;Downloading the LaTeX engine (Tectonic)…&quot; with a percentage</li><li>&quot;Installing the LaTeX engine…&quot;</li><li>&quot;Downloading the standard LaTeX packages (first run only, a few minutes)…&quot;</li></ul><p>If setup fails, for example because you&#39;re offline, the banner says &quot;LaTeX setup failed&quot; with the reason and a <strong>Try again</strong> button. The status panel in the top bar offers <strong>Retry LaTeX setup</strong> too, and Tilepress tries again the next time it starts. If you already have MiKTeX or TeX Live installed, nothing is downloaded. If Tectonic is already on your <code>PATH</code>, Tilepress uses that copy and only runs the one-time package download. If no engine is installed and setup hasn&#39;t started, the banner says so and offers <strong>Install now</strong>.</p><p>Tectonic downloads any other package the first time a document uses it, so a document with new packages needs an internet connection the first time you compile it. See <a href="/tilepress/docs/privacy">Privacy</a>.</p><h3 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li><strong>Compiling saves first.</strong> Every compile, including Live ones, writes the source to the <code>.tex</code> file before compiling it.</li><li><strong>Where the PDF goes.</strong> The PDF is written next to the <code>.tex</code> file with the same name: <code>thesis.tex</code> makes <code>thesis.pdf</code>. A PDF of that name is replaced. The log and other working files go in a <code>.toolbox-build</code> folder next to the <code>.tex</code> file.</li><li><strong>New documents</strong> are created as <code>main.tex</code> in <code>%LOCALAPPDATA%\\Tilepress\\latex\\untitled-1</code> (then <code>untitled-2</code> and so on), and their PDF is written there too. <strong>Save as…</strong> suggests <code>document.tex</code> in your Documents folder. After that you&#39;re editing the saved copy, and the untitled folder stays where it was.</li><li>pdfLaTeX, XeLaTeX and LuaLaTeX are run a second time when the log asks for it, so cross-references and the table of contents come out right.</li><li>A compile that takes longer than 5 minutes is stopped.</li><li>The document compiles once when you open it, if an engine is ready.</li><li>If you edit while a compile is running, one more compile follows when it finishes.</li><li><strong>Recent</strong> lists the last eight <code>.tex</code> files you opened or saved.</li><li>LaTeX compiles are not recorded in <a href="/tilepress/docs/history">History</a>.</li></ul>',30)])])}const u=t(r,[["render",s]]);export{p as __pageData,u as default};
